SELECT r.target_id AS target_id, r.reason AS reason, COUNT(*) AS report_count FROM community_report r WHERE r.reviewed_at IS NULL AND r.target_type = #{targetType} AND r.target_id IN
#{targetId}
GROUP BY r.target_id, r.reason

SELECT ranked.target_id AS target_id, ranked.reason AS reason, ranked.content AS content, ranked.created_at AS created_at FROM ( SELECT r.target_id AS target_id, r.reason AS reason, r.content AS content, r.created_at AS created_at, ROW_NUMBER() OVER (PARTITION BY r.target_id ORDER BY r.created_at DESC, r.id DESC) AS row_num FROM community_report r WHERE r.reviewed_at IS NULL AND r.target_type = #{targetType} AND r.target_id IN
#{targetId}
) ranked WHERE ranked.row_num <= 5 ORDER BY ranked.target_id ASC, ranked.row_num ASC
